// Calculate the perimeter of a closed polygon
function perimeter(points) {
    // Validate input
    if (!Array.isArray(points)) {
        throw new Error("perimeter: points must be an array");
    }
    if (points.length < 2) {
        throw new Error("perimeter: a polygon must have at least 2 vertices");
    }

    for (let i = 0; i < points.length; i++) {
        const point = points[i];
        if (!point || typeof point !== 'object' || point.x === undefined || point.y === undefined) {
            throw new Error(`perimeter: point at index ${i} must be an object with x and y properties`);
        }
        if (typeof point.x !== 'number' || !isFinite(point.x)) {
            throw new Error(`perimeter: point at index ${i} has invalid x coordinate: ${point.x}`);
        }
        if (typeof point.y !== 'number' || !isFinite(point.y)) {
            throw new Error(`perimeter: point at index ${i} has invalid y coordinate: ${point.y}`);
        }
    }

    let total = 0;
    const n = points.length;

    for (let i = 0; i < n; i++) {
        const j = (i + 1) % n;
        total += distance(points[i], points[j]);
    }

    return total;
}

class Store:
    def __init__(self, now=None, max_keys=None):
        self._data = {}
        self._transactions = []
        self._now = now or time.time
        self._max_keys = max_keys

def set(self, key, value, ttl=None):
    # If we're in a transaction, modify the transaction data
    # Otherwise, modify the main data
    if self._transactions:
        # Check if this is a new key (not already in the transaction or main data)
        is_new_key = key not in self._transactions[-1] and key not in self._data
        if is_new_key and self._max_keys is not None:
            # Count current live keys
            live_keys = set()
            now = self._now()

            # Check main data
            for k, item in self._data.items():
                v, set_time, t = item
                if t is None or now < set_time + t:
                    live_keys.add(k)

            # Check transaction data
            for transaction in self._transactions:
                for k, item in transaction.items():
                    v, set_time, t = item
                    if t is None or now < set_time + t:
                        live_keys.add(k)

            # If we're at max capacity, raise OverflowError
            if len(live_keys) >= self._max_keys:
                raise OverflowError("Store is at maximum capacity")

        self._transactions[-1][key] = (value, self._now(), ttl)
    else:
        # Check if this is a new key (not already in the main data)
