// Function to format cents into money strings
function formatMoney(cents, code = 'USD') {
    // Handle negative amounts
    const isNegative = cents < 0;
    const absCents = Math.abs(cents);

    // Convert cents to dollars
    const dollars = absCents / 100;

    // Format with commas and 2 decimal places
    const formatted = dollars.toLocaleString('en-US', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
    });

    // Determine currency symbol based on code
    let symbol;
    switch(code) {
        case 'USD':
            symbol = '$';
            break;
        case 'EUR':
            symbol = '€';
            break;
        case 'GBP':
            symbol = '£';
            break;
        default:
            return (isNegative ? '-' : '') + code + ' ' + formatted;
    }

    // Add currency symbol and negative sign if needed
    return (isNegative ? '-' : '') + symbol + formatted;
}

