document.addEventListener('DOMContentLoaded', function() {
    const input = document.getElementById('r9-input');
    const list = document.getElementById('r9-list');
    const clearButton = document.getElementById('r9-clear');

    // Load saved items from localStorage
    function loadItems() {
        const savedItems = localStorage.getItem('r9-items');
        if (savedItems) {
            const items = JSON.parse(savedItems);
            items.forEach(item => {
                const li = document.createElement('li');
                li.textContent = item.text;
                if (item.done) {
                    li.classList.add('done');
                }
                list.appendChild(li);
            });
        }
    }

    // Save items to localStorage
    function saveItems() {
        const items = [];
        list.querySelectorAll('li').forEach(li => {
            items.push({
                text: li.textContent,
                done: li.classList.contains('done')
            });
        });
        localStorage.setItem('r9-items', JSON.stringify(items));
    }

    // Load items when page loads
    loadItems();

    input.addEventListener('keypress', function(event) {
        if (event.key === 'Enter') {
            const text = input.value.trim();
            if (text.length > 0) {
                const li = document.createElement('li');
                li.textContent = text;
                list.appendChild(li);
                input.value = '';
                saveItems(); // Save after adding new item
            }
        }
    });

    // Mark item as done when clicked
    list.addEventListener('click', function(event) {
        if (event.target.tagName === 'LI') {
            event.target.classList.toggle('done');
            saveItems(); // Save after toggling done state
        }
    });

    clearButton.addEventListener('click', function() {
        // Filter out done items (items with class "done")
        const items = list.querySelectorAll('li');
        items.forEach(item => {
            if (item.classList.contains('done')) {
                item.remove();
            }
        });
        saveItems(); // Save after clearing done items
    });
});

  toCSV() {
    // Create header line
    let csv = 'account,balance';

    // Get all accounts and sort them by name
    const sortedAccounts = Array.from(this.accounts.entries()).sort(([a], [b]) => a.localeCompare(b));

    // Add each account with its balance formatted to 2 decimal places
    for (const [name, balance] of sortedAccounts) {
      csv += `\n${name},${balance.toFixed(2)}`;
    }

    return csv;
  }

  static fromCSV(text) {
    // Parse CSV text into lines
    const lines = text.trim().split('\n');

    // Check for empty input
    if (lines.length === 0) {
      throw new Error("CSV data is empty");
    }

    // Check header line
    const header = lines[0];
    if (header !== 'account,balance') {
      throw new Error(`Invalid header: expected "account,balance", got "${header}"`);
    }

    // Create new ledger
    const ledger = new Ledger();

    // Process each data line
    for (let i = 1; i < lines.length; i++) {
      const line = lines[i].trim();

      // Skip empty lines
      if (line === '') continue;

      // Split line by comma
      const parts = line.split(',');

      // Check line format
      if (parts.length !== 2) {
        throw new Error(`Malformed line: ${line}`);
      }

      const accountName = parts[0];
      const balanceStr = parts[1];

      // Validate account name
      if (accountName === '') {
        throw new Error(`Empty account name in line: ${line}`);
      }

      // Parse balance
      const balance = parseFloat(balanceStr);

      // Validate balance
      if (isNaN(balance) || balance < 0) {
        throw new Error(`Invalid balance "${balanceStr}" in line: ${line}`);
      }

      // Open account
      ledger.open(accountName);

      // If balance is positive, make a deposit
      if (balance > 0) {
        ledger.deposit(accountName, balance);
      }
    }

    return ledger;
  }
}

