def to_text(grid):
    """Convert a grid to text where True means open and False means wall.

    Args:
        grid (list[list[bool]]): Grid as list of rows of booleans (True = open)

    Returns:
        str: Grid text with lines separated by newlines ('.' for True, '#' for False)
    """
    if not grid:
        return ""

    lines = []
    for row in grid:
        line = ""
        for cell in row:
            line += '.' if cell else '#'
        lines.append(line)

    return '\n'.join(lines)


